def solve(rows):
    if not rows:
        return []
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 4 != 3 or i == len(rows) - 1:
            filtered_rows.append(row)
    if filtered_rows:
        length = len(filtered_rows)
        rotated_rows = filtered_rows[2 % length:] + filtered_rows[:2 % length]
    else:
        rotated_rows = []
    unique_rows = sorted(list(set(rotated_rows)))
    sessions = []
    if not unique_rows:
        return sessions
    start = unique_rows[0]
    end = unique_rows[0]
    count = 1
    for i in range(1, len(unique_rows)):
        if unique_rows[i] - end >= 4:
            sessions.append([start, end, count])
            start = unique_rows[i]
            end = unique_rows[i]
            count = 1
        else:
            end = unique_rows[i]
            count += 1
    sessions.append([start, end, count])
    return sessions

